#!/usr/bin/env node
/**
 * inject-env-config.mjs
 *
 * Reads MiniMax / OpenCode API settings from `.env` (project root, falling
 * back to the parent directory) and emits `src/shared/env-config.generated.ts`.
 * The generated file is gitignored.
 *
 * Build pipeline integration:
 *   pnpm build
 *     -> node scripts/inject-env-config.mjs   (this script)
 *     -> node scripts/copy-tesseract.js
 *     -> tsc --noEmit
 *     -> vite build
 *
 * If `.env` is missing, the generated file contains empty defaults and a
 * warning is printed. Build still succeeds (the extension will be unusable
 * until keys are provided).
 */

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const PROJECT_ROOT = resolve(__dirname, '..');

function candidateEnvPaths() {
  const explicit = process.env['MT_ENV_FILE'];
  const paths = explicit ? [resolve(process.cwd(), explicit)] : [];
  // Search up to three levels above the project root. The owner keeps a
  // master .env at ~/Code/.env which is ../../ from the project root.
  for (let up = 0; up <= 3; up++) {
    paths.push(join(PROJECT_ROOT, ...Array(up).fill('..'), '.env'));
  }
  return paths;
}

function findEnvFile() {
  for (const candidate of candidateEnvPaths()) {
    if (existsSync(candidate)) {
      return candidate;
    }
  }
  return null;
}

function parseEnv(content) {
  const out = {};
  for (const rawLine of content.split('\n')) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq <= 0) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    // Strip surrounding quotes
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    out[key] = value;
  }
  return out;
}

function buildEnvConfig(env) {
  return {
    minimax: {
      baseUrl: env['MINIMAX_API_PATH'] ?? '',
      apiKey: env['MINIMAX_API_KEY'] ?? '',
      model: env['MINIMAX_API_MODEL'] ?? '',
    },
    opencode: {
      baseUrl: env['OPEN_CODE_API_PATH'] ?? '',
      apiKey: env['OPEN_CODE_API_KEY'] ?? '',
      model: env['OPEN_CODE_API_MODEL'] ?? '',
    },
  };
}

function renderGeneratedTs(config) {
  return `// AUTO-GENERATED by scripts/inject-env-config.mjs — DO NOT EDIT.
// This file is gitignored. Regenerate by running \`pnpm build\`.

export const ENV_CONFIG = ${JSON.stringify(config, null, 2)} as const;
`;
}

function main() {
  const envPath = findEnvFile();
  const config = envPath
    ? buildEnvConfig(parseEnv(readFileSync(envPath, 'utf8')))
    : { minimax: { baseUrl: '', apiKey: '', model: '' }, opencode: { baseUrl: '', apiKey: '', model: '' } };

  const outPath = join(PROJECT_ROOT, 'src', 'shared', 'env-config.generated.ts');
  writeFileSync(outPath, renderGeneratedTs(config), 'utf8');

  if (envPath) {
    const maskedKeys = Object.entries({
      minimax: config.minimax.apiKey,
      opencode: config.opencode.apiKey,
    }).map(([name, key]) => `${name}=${key ? `${key.slice(0, 6)}…(${key.length})` : 'empty'}`);
    console.log(`[inject-env] loaded ${envPath}`);
    console.log(`[inject-env]   ${maskedKeys.join('  ')}`);
  } else {
    console.warn(
      '[inject-env] no .env found at ' +
        candidateEnvPaths().join(' or ') +
        '; generated file has empty placeholders.'
    );
  }
  console.log(`[inject-env] wrote ${outPath}`);
}

main();
